<template>
  <div class="eval-page">
    <header class="page-header"><div><div class="page-eyebrow">QUALITY LAB / EXP-024</div><h2>{{ t('evaluation.title') }}</h2><p class="page-subtitle">{{ t('evaluation.subtitle') }}</p></div><div class="actions"><span><i /> AUTH-REGRESSION · 24 CASES</span><el-button type="primary" @click="run">{{ t('evaluation.run') }}</el-button></div></header>
    <section class="experiment-strip"><div><span>{{ t('evaluation.experiment') }}</span><b>{{ t('evaluation.authExperiment') }}</b></div><div><span>{{ t('evaluation.judge') }}</span><b>Evidence Judge v2</b></div><div><span>{{ t('evaluation.lastRun') }}</span><b>21:08 · 02m 46s</b></div><div><span>{{ t('evaluation.gates') }}</span><b class="pass">6 / 7 {{ t('evaluation.passed') }}</b></div></section>
    <main class="lab-grid">
      <section class="comparison panel">
        <div class="panel-header"><div><span>{{ t('evaluation.modelComparison') }}</span><small>{{ t('evaluation.sameDataset') }}</small></div><div class="legend"><i class="a" /> v1.3 <i class="b" /> v1.2</div></div>
        <div class="candidate row"><span>{{ t('evaluation.metric') }}</span><div><b>Agent v1.3</b><small>GPT-5 · prompt-13</small></div><div><b>Agent v1.2</b><small>Qwen-X · prompt-12</small></div><span class="right">DELTA</span></div>
        <div v-for="m in metrics" :key="m.label" class="metric row"><div><b>{{ m.label }}</b><small>{{ m.hint }}</small></div><div class="score"><strong class="mono">{{ m.a }}%</strong><i><em :style="{width:m.a+'%'}" /></i></div><div class="score old"><strong class="mono">{{ m.b }}%</strong><i><em :style="{width:m.b+'%'}" /></i></div><strong class="delta mono">+{{ m.a-m.b }}%</strong></div>
