      <aside class="verdict panel">
        <div class="panel-header"><span>{{ t('evaluation.verdict') }}</span><small class="pass">READY</small></div>
        <div class="winner"><span>{{ t('evaluation.recommended') }}</span><strong>Agent v1.3</strong><p>{{ t('evaluation.verdictText') }}</p></div>
