  </div>
</template>
<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'; import { useI18n } from 'vue-i18n'; import { ElMessage } from 'element-plus/es/components/message/index.mjs'; import { useAppStore } from '@/stores/app'; import { evaluationApi } from '@/api'; import type { AgentEvaluation } from '@/types'; import { demoEvaluations } from '@/data/demo'
const {t}=useI18n(),store=useAppStore(); const evaluations=ref<AgentEvaluation[]>([])
const metrics=computed(()=>[{label:t('evaluation.requirementScore'),hint:t('evaluation.hintRequirement'),a:94,b:91},{label:t('evaluation.testCaseScore'),hint:t('evaluation.hintQuality'),a:90,b:86},{label:t('evaluation.coverageScore'),hint:t('evaluation.hintCoverage'),a:84,b:79},{label:t('evaluation.bugDetection'),hint:t('evaluation.hintBugs'),a:92,b:88},{label:t('evaluation.toolAccuracy'),hint:t('evaluation.hintTools'),a:96,b:90},{label:t('evaluation.completionScore'),hint:t('evaluation.hintCompletion'),a:89,b:85}])
const gates=computed(()=>[{name:t('evaluation.gateCompletion'),value:'89% ≥ 85%',pass:true},{name:t('evaluation.gateEvidence'),value:'100%',pass:true},{name:t('evaluation.gateHallucination'),value:'1.2% ≤ 2%',pass:true},{name:t('evaluation.gateLatency'),value:'2m46s ≤ 3m',pass:true},{name:t('evaluation.gateCoverage'),value:'84% < 85%',pass:false}])
const pct=(v?:number)=>v!=null?`${Math.round(v*100)}%`:'—'; const run=()=>ElMessage.success(t('evaluation.runStarted')); const promote=()=>ElMessage.success(t('evaluation.promoted'))
async function load(){if(!store.currentProject)return;if(store.isDemoMode){evaluations.value=demoEvaluations;return}try{const r=await evaluationApi.listByProject(store.currentProject.id);evaluations.value=r.data?.length?r.data:demoEvaluations}catch{evaluations.value=demoEvaluations}}
onMounted(load);watch(()=>store.currentProject,load)
</script>
