ore{display:flex;align-items:center;gap:9px}.score strong{width:36px;font-size:12px}.score>i{width:72px;height:3px;background:var(--bg-base)}.score em{display:block;height:100%;background:var(--primary)}.score.old em{background:var(--text-muted)}.delta{color:var(--success);font-size:11px;text-align:right}.verdict{overflow:hidden}.winner{padding:18px 16px 14px}.winner>span{color:var(--text-muted);font-size:9px;text-transform:uppercase}.winner>strong{display:block;margin:5px 0;font-size:20px}.winner p{color:var(--text-secondary);font-size:11px;line-height:1.6}.gates{padding:0 16px}.gates>div{display:flex;justify-content:space-between;min-height:34px;align-items:center;border-top:1px solid var(--border-subtle);font-size:10px}.gates span{display:flex;align-items:center;gap:7px}.gates i{width:6px;height:6px;border-radius:50%}.ok{background:var(--success)}.warn{background:var(--warning)}.gates b{font-size:9px}.watch{display:flex;gap:9px;margin:14px 16px;padding:10px;border-left:2px solid var(--warning);background:color-mix(in srgb,var(--warning) 7%,transparent);color:var(--warning)}.watch p{color:var(--text-muted);font-size:10px;line-height:1.5}.watch p strong{display:block;color:var(--text-secondary)}.promote{width:calc(100% - 32px);margin:0 16px 16px}.history{margin-top:12px;overflow:hidden}.history-row{display:grid;grid-template-columns:90px 110px 100px 1fr 1fr 160px;align-items:center;min-height:42px;padding:0 14px;border-top:1px solid var(--border-subtle);color:var(--text-secondary);font-size:10px}.history-row> b{font-size:11px}.history-row time{text-align:right;color:var(--text-muted)}
